-- MARKET-SCAN-1 (2026-11-12, charter pillar autonomy; owner directive: virtual agents do what a product manager does: research users, analyse competitors, adopt best practice, then build it).
-- SOTA-SCAN-1 covers one program (OPS) on technique topics. This adds the outward-facing PM loop for every lane that originates roadmap work: each day one program
-- (REACH, RSCH, INFRA, OPS in rotation) runs one lens (competitor teardown, user needs, cutting-edge practice in rotation) and names three or more players. The reply goes through
-- the ROADMAP-ORIGINATE-1 steps (instance roadmap-<program>-comp-<date>) into a ROADMAP-1 issue, code task, merged PR and measured outcome. PERSONAL is excluded (lane rule).
-- Stop: INSERT OR REPLACE INTO ops_config (key, value) VALUES ('market_scan', 'off'). Read: SELECT * FROM v_market_scan;
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261112_market_scan_workflow
-- Rollback: UPDATE fleet_tasks SET definition = (SELECT definition FROM bak_20261112_market_scan_workflow WHERE id = 'domain-managers'), version = version + 1 WHERE id = 'domain-managers'; DROP VIEW IF EXISTS v_market_scan;

CREATE TABLE IF NOT EXISTS bak_20261112_market_scan_workflow AS SELECT id, definition, version FROM fleet_tasks WHERE id = 'domain-managers';

INSERT OR IGNORE INTO ops_config (key, value, note, updated_at) VALUES ('market_scan', 'on', 'MARKET-SCAN-1 daily competitor/user-need/best-practice scan per program; off stops it', datetime('now'));

DROP VIEW IF EXISTS v_market_scan;
CREATE VIEW v_market_scan AS
SELECT p.id, p.request_instance, p.title, p.status, p.issue_id, p.task_id, p.pr_url, p.outcome, p.created_at, p.deployed_at
FROM roadmap_proposals p WHERE p.request_instance LIKE 'roadmap-QNFO.%-comp-%';

UPDATE fleet_tasks
SET definition = json_insert(definition, '$.steps[#]', json('{"type":"sql","name":"market-scan","db":"AUDIT","sql":"INSERT INTO cf_agent_requests (requester, kind, prompt, instance, priority) SELECT ''program-manager:'' || p.code, ''run'', ''You are the product manager of program '' || p.code || '' in the QNFO fleet (repository QNFO/qnfo-workers, Cloudflare Workers plus the D1 database qnfo-audit): an autonomous fleet that publishes research, reaches readers and runs its own administration. A product manager looks outward every day: researches users and competitors, benchmarks against the best, and ships what it learns. Program focus: '' || p.focus || ''. Lens today: '' || p.lens || ''. Search the web (competitor products and changelogs, vendor engineering blogs, arXiv, user forums, review sites, Cloudflare docs) for evidence from the last 12 months. Name the specific players (at least three), what each does better than the fleet, the unmet user need, and the biggest gap. Cheap models wherever they work; quality never drops. Already proposed (do not repeat): '' || COALESCE((SELECT group_concat(substr(title, 1, 70), ''; '') FROM (SELECT title FROM roadmap_proposals WHERE request_instance LIKE ''roadmap-'' || p.code || ''-comp-%'' ORDER BY id DESC LIMIT 10)), ''none'') || ''. Propose ONE improvement that a single-file change can deliver. Reply in exactly this form, each on its own line:'' || char(10) || ''TITLE: <under 80 characters, start with MARKET:>'' || char(10) || ''WHY: <players, source URL, the user need, the gap here and the metric that will show it helped, under 90 words>'' || char(10) || ''code-task: repo=qnfo-workers path=<one worker.js, never qnfo-fleet-control, qnfo-ops, qnfo-deploy-guard, qnfo-code-orchestrator, .github or a personal-* path>'' || char(10) || ''code-anchor: <verbatim text that occurs exactly once in that file, next to the edit>'' || char(10) || ''EDIT: <the exact change, under 120 words>'', ''roadmap-'' || p.code || ''-comp-'' || strftime(''%Y%m%d'', ''now''), ''medium'' FROM (SELECT CASE d % 4 WHEN 0 THEN ''QNFO.REACH'' WHEN 1 THEN ''QNFO.RSCH'' WHEN 2 THEN ''QNFO.INFRA'' ELSE ''QNFO.OPS'' END AS code, CASE d % 4 WHEN 0 THEN ''audience growth: newsletters, social distribution, SEO and AI-search visibility for research publishers'' WHEN 1 THEN ''research quality: AI research assistants, preprint servers, peer-review and citation tooling, reproducibility'' WHEN 2 THEN ''platform reliability and cost: serverless and edge platforms, observability, incident response, FinOps for LLM spend'' ELSE ''autonomous operations: agent platforms, workflow engines, developer-productivity and AIOps products'' END AS focus, CASE (d / 4) % 3 WHEN 0 THEN ''competitor teardown (features, pricing, changelogs, what they shipped lately)'' WHEN 1 THEN ''user needs (complaints, requests and jobs-to-be-done on forums, reviews and issue trackers)'' ELSE ''best practices from the cutting edge (engineering blogs, papers, standards)'' END AS lens FROM (SELECT CAST(strftime(''%j'', ''now'') AS INTEGER) AS d)) p WHERE EXISTS (SELECT 1 FROM program_charters c WHERE c.program_code = p.code AND c.status = ''active'') AND NOT EXISTS (SELECT 1 FROM cf_agent_requests r WHERE r.instance = ''roadmap-'' || p.code || ''-comp-'' || strftime(''%Y%m%d'', ''now'') AND (r.status IN (''queued'', ''running'') OR (r.status = ''done'' AND COALESCE(r.result, '''') <> '''' AND COALESCE(r.result, '''') NOT LIKE ''(the model returned no text)%''))) AND COALESCE((SELECT value FROM ops_config WHERE key = ''persona_actions''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''roadmap_originate''), ''on'') <> ''off'' AND COALESCE((SELECT value FROM ops_config WHERE key = ''market_scan''), ''on'') <> ''off''"}')), version = version + 1
WHERE id = 'domain-managers' AND instr(definition, '"market-scan"') = 0;
